def hop_counts(G, source, target):
    return nx.shortest_path_length(G, source, target)


from queue import PriorityQueue

def check_path_conflict(dir, core1, src1, sink1, core2, src2, sink2):

    ys1 = dir[src1][0].item()
    xs1 = dir[src1][1].item()
    yc1 = dir[core1][0].item()
    xc1 = dir[core1][1].item()
    yk1 = dir[sink1][0].item()
    xk1 = dir[sink1][1].item()
    ys2 = dir[src2][0].item()
    xs2 = dir[src2][1].item()
    yc2 = dir[core2][0].item()
    xc2 = dir[core2][1].item()
    yk2 = dir[sink2][0].item()
    xk2 = dir[sink2][1].item()

  # print(xc1, yc1)
  # print(xs1, ys1)
  # print(xk1, yk1)
  # print(xc2, yc2)
  # print(xs2, ys2)
  # print(xk2, yk2)

    if (xs1-xc1)*(xs2-xc2) > 0:
        if not((xc1 <= min(xc2,xs2) and xs1 <= min(xc2,xs2)) or (xc1 >= max(xc2,xs2) and xs1 >= max(xc2,xs2))) and ys1==ys2:
            # print('F')
            return True
    if (xs1-xc1)*(xc2-xk2) > 0:
        if not((xc1 <= min(xc2,xk2) and xs1 <= min(xc2,xk2)) or (xc1 >= max(xc2,xk2) and xs1 >= max(xc2,xk2))) and ys1==yc2:
            # print('G')
            return True
    if (xc1-xk1)*(xs2-xc2) > 0:
        if not((xc1 <= min(xc2,xs2) and xk1 <= min(xc2,xs2)) or (xc1 >= max(xc2,xs2) and xk1 >= max(xc2,xs2))) and yc1==ys2:
            # print('H')
            return True
    if (xc1-xk1)*(xc2-xk2) > 0:
        if not((xc1 <= min(xc2,xk2) and xk1 <= min(xc2,xk2)) or (xc1 >= max(xc2,xk2) and xk1 >= max(xc2,xk2))) and yc1==yc2:
            # print('I')
            return True
    if (ys1-yc1)*(ys2-yc2) > 0:
        if not((yc1 <= min(yc2,ys2) and ys1 <= min(yc2,ys2)) or (yc1 >= max(yc2,ys2) and ys1 >= max(yc2,ys2))) and xc1==xc2:
            # print('J')
            return True
    if (ys1-yc1)*(yc2-yk2) > 0:
        if not((yc1 <= min(yc2,yk2) and ys1 <= min(yc2,yk2)) or (yc1 >= max(yc2,yk2) and ys1 >= max(yc2,yk2))) and xc1==xk2:
            # print('K')
            return True
    if (yc1-yk1)*(ys2-yc2) > 0:
        if not((yc1 <= min(yc2,ys2) and yk1 <= min(yc2,ys2)) or (yc1 >= max(yc2,ys2) and yk1 >= max(yc2,ys2))) and xk1==xc2:
            # print('L')
            return True
    if (yc1-yk1)*(yc2-yk2) > 0:
        if not((yc1 <= min(yc2,yk2) and yk1 <= min(yc2,yk2)) or (yc1 >= max(yc2,yk2) and yk1 >= max(yc2,yk2))) and xk1==xk2:
            # print('M')
            return True

    return False



# (up,left,down,right) = (0,1,2,3)
def objFunct(mappings, dir, cores, io_array, dims, graphs):
    num_samples =  len(mappings)//len(cores) + 1
    penalty = []
    orders = []
    for k,maps in enumerate(mappings):
        io_data = [[] for _ in range(len(io_array))]
        for i,m in enumerate(maps):
            io_data[m].append(i)
        # print(f"io_data: {io_data}")
        start_time = [0]*len(maps)
        global_time = [0]*len(io_array)
        allocated = [False]*len(maps)
        in_passive = [False]*len(maps)
        test_times = [[] for _ in range(len(io_array))]
        for j in range(len(io_data)):
            for c in range(len(io_data[j])):
                core=io_data[j][c]+1
                io = io_array[int(maps[core-1])]
                src= io[0]-1
                sink = io[1]-1
                hsc = hop_counts(graphs, src+1, core)
                hck = hop_counts(graphs, core, sink+1)
                l = cores[k//num_samples][j].scan
                p = cores[k//num_samples][j].patterns
                time = (max(hsc,hck)+l)*p + (min(hsc,hck)+l-1)
                test_times[j].append(time)
        alloc = []
        pass_arr = PriorityQueue()
        # print(f"Test times: {test_times}")
        while (False in allocated):
        # if (len(pass_arr) == 0) or is_passive(maps, global_time, start_time, pass_arr):
        # print(f"Global time: {global_time}")
        # print(f"Start time: {start_time}")
        # print(f"Current allocations: {alloc}")
        # print(f"Passive Queue: {pass_arr.queue}")
            temp_passive = []
            while not pass_arr.empty():
                strt, core = pass_arr.get()
                if allocated[core]:
                    continue
                # print(f"infinite loop, {core}")
                is_conflict = False
                io_idx = maps[core]
                core_in_io_indx = io_data[io_idx].index(core)
                for a, all in enumerate(alloc):
                    if start_time[core] < all[1]:
                        # print("FFF", core, alloc)
                        # Checking for path conflict
                        core1 = core
                        src1 = io_array[io_idx][0]-1
                        sink1 = io_array[io_idx][1]-1
                        core2 = all[0]
                        src2 = io_array[maps[all[0]]][0]-1
                        sink2 = io_array[maps[all[0]]][1]-1
                        is_conflict = check_path_conflict(dir, core1, src1, sink1, core2, src2, sink2)
                        # print(core,all[0], is_conflict)
                        if is_conflict:
                            temp_passive.append(core)
                            start_time[core] = max(start_time[core], global_time[maps[all[0]]])
                            break
                if not is_conflict:
                    allocated[core] = True
                    alloc.append((core,start_time[core]+test_times[io_idx][core_in_io_indx]))
                    global_time[io_idx] = start_time[core]+test_times[io_idx][core_in_io_indx]
                    for c in io_data[io_idx]:
                        if not allocated[c]:
                            start_time[c] = max(start_time[c], global_time[io_idx])
                    for conf in temp_passive:
                        start_time[conf] = max(start_time[conf], global_time[io_idx])

                    break
            if len(temp_passive) > 0:
                for c in temp_passive:
                    pass_arr.put((start_time[c],c))
                    in_passive[c] = True

            for idx, io in enumerate(io_data):
                temp_conflict = []
                for indx, c in enumerate(io):
                    if allocated[c] or in_passive[c]:
                        continue
                    is_conflict = False
                    for a, all in enumerate(alloc):
                        if start_time[c] < all[1]:
                        # Checking for path conflict
                            core1 = c
                            src1 = io_array[idx][0]-1
                            sink1 = io_array[idx][1]-1
                            core2 = all[0]
                            src2 = io_array[maps[all[0]]][0]-1
                            sink2 = io_array[maps[all[0]]][1]-1
                            is_conflict = check_path_conflict(dir, core1, src1, sink1, core2, src2, sink2)
                            # print(c,all[0], is_conflict)
                            if is_conflict:
                                temp_conflict.append(c)
                                start_time[c] = max(start_time[c], global_time[maps[all[0]]])
                                break
                    if not is_conflict:
                        allocated[c] = True
                        alloc.append((c,start_time[c]+test_times[idx][indx]))
                        global_time[idx] = start_time[c]+test_times[idx][indx]
                        for core in io:
                            if not allocated[core]:
                                start_time[core] = max(start_time[core], global_time[idx])
                        for conf in temp_conflict:
                            start_time[conf] = max(start_time[conf], global_time[idx])
                            pass_arr.put((start_time[conf],conf))
                            in_passive[conf] = True
                        temp_conflict = []
                        break
                    for c in temp_conflict:
                        pass_arr.put((start_time[c],c))
                        in_passive[c] = True

                    temp = []
                    while not pass_arr.empty():
                        start, core = pass_arr.get()
                        temp.append(core)
                    for c in temp:
                        pass_arr.put((start_time[c],c))

    penalty.append(np.max(global_time)*(-1))
    orders.append([item[0] for item in alloc])
  # print(f"Global time: {global_time}")
  # print(f"Start time: {start_time}")
    # print(f"Current allocations: {alloc}")
    # print(f"Passive Queue: {pass_arr.queue}")
    return torch.from_numpy(np.array(penalty)), orders



class Individual:  # Mapping: possible solution to NoC testing problem
    def __init__(self, genes):
        self.genes = genes  # Represents a mapping (e.g., order of IO to cores)
        self.__reset_params()

    def swap(self, gene_1, gene_2):
        """Mutate by swapping two cores in the mapping."""
        a, b = self.genes.index(gene_1), self.genes.index(gene_2)
        self.genes[b], self.genes[a] = self.genes[a], self.genes[b]
        self.__reset_params()

    def add(self, gene):
        self.genes.append(gene)
        self.__reset_params()

    @property
    def fitness(self):
        """Calculate fitness using the given objective function."""
        if self.__fitness == 0:
            mappings = [self.genes]
            penalty, order = objFunct(mappings, dir[0], cores_list, io_array, dims, graphs)  # Assuming batch element 0
            self.__fitness = penalty.item()  # Maximize negative penalty (equivalent to minimizing penalty)
        return self.__fitness

    def __reset_params(self):
        self.__fitness = 0


class Population:  # Population of individuals
    def __init__(self, individuals):
        self.individuals = individuals

    @staticmethod
    def gen_individuals(sz, genes):
        """Initialize a population of individuals with random mappings."""
        individuals = []
        for _ in range(sz):
            individuals.append(Individual(sample(genes, len(genes))))
        return Population(individuals)

    def add(self, individual):
        self.individuals.append(individual)

    def rmv(self, individual):
        self.individuals.remove(individual)

    def get_fittest(self):
        """Return the individual with the highest fitness."""
        fittest = self.individuals[0]
        for ind in self.individuals:
            if ind.fitness > fittest.fitness:
                fittest = ind
        return fittest


def evolve(pop, tourn_size, mut_rate):
    new_generation = Population([])
    pop_size = len(pop.individuals)
    elitism_num = pop_size // 2

    # Elitism: Preserve best individuals
    for _ in range(elitism_num):
        fittest = pop.get_fittest()
        new_generation.add(fittest)
        pop.rmv(fittest)

    # Crossover
    for _ in range(elitism_num, pop_size):
        parent_1 = selection(new_generation, tourn_size)
        parent_2 = selection(new_generation, tourn_size)
        child = crossover(parent_1, parent_2)
        new_generation.add(child)

    # Mutation
    for i in range(elitism_num, pop_size):
        mutate(new_generation.individuals[i], mut_rate)

    return new_generation


def crossover(parent_1, parent_2):
    """Perform ordered crossover to produce a child."""
    genes_n = len(parent_1.genes)
    child = Individual([None] * genes_n)

    # Fill half genes from parent 1
    start_at = randint(0, genes_n // 2)
    end_at = start_at + genes_n // 2
    for i in range(start_at, end_at):
        child.genes[i] = parent_1.genes[i]

    # Fill rest from parent 2
    for i in range(genes_n):
        if i<start_at or i>=end_at:
            child.genes[i] = parent_2.genes[i]

    return child


def mutate(individual, rate):
    """Mutate an individual by swapping genes."""
    for _ in range(len(individual.genes)):
        if random() < rate:
            sel_genes = sample(individual.genes, 2)
            individual.swap(sel_genes[0], sel_genes[1])


def selection(population, competitors_n):
    """Select the fittest individual from a random subset of the population."""
    return Population(sample(population.individuals, competitors_n)).get_fittest()

#gen_individuals fucntion is used to generate population randomly, 
#while when you want for active_Search tested data, use individuals and then generate population.

def run_ga(genes, pop_size, n_gen, tourn_size, mut_rate, verbose=1):
    """Run the genetic algorithm."""
    #population = Population.gen_individuals(pop_size, genes)
    individuals = [Individual(list(row)) for row in data_64_2io]
    population = Population(individuals)
    history = {'cost': [population.get_fittest().fitness]}
    counter, generations, max_fitness = 0, 0, float('-inf')

    if verbose:
        print("-- NoC-GA -- Initiating evolution...")

    start_time = time()
    while counter < n_gen:
        population = evolve(population, tourn_size, mut_rate)
        fitness = population.get_fittest().fitness

        if fitness > max_fitness:
            counter, max_fitness = 0, fitness
        else:
            counter += 1

        generations += 1
        history['cost'].append(fitness)
        # print(f"Counter {counter} done")
    
    total_time = round(time() - start_time, 6)

    if verbose:
        print(f"-- NoC-GA -- Evolution finished after {generations} generations in {total_time} s")
        print(f"-- NoC-GA -- Maximum fitness (minimum penalty): {max_fitness}")

    history['generations'] = generations
    history['total_time'] = total_time
    history['route'] = population.get_fittest().genes

    return history


# Run the Genetic Algorithm
genes = [randint(0,len(io_array)-1) for _ in range(len(cores_list[0]))]
best_mapping_history = run_ga(genes, pop_size=50, n_gen=1000, tourn_size=5, mut_rate=0.2)
print("Best Mapping Found: ", best_mapping_history['route'])
